use std::{fs,path::Path};fn main(){let arg=std::env::args().nth(1).unwrap();let p=Path::new(&arg);let first=fs::read_to_string(p.join("CONTROL.tsv")).unwrap();let shifted=fs::read_to_string(p.join("SHIFT-CONTROL.tsv")).unwrap();let mut summary=String::from("g\tp\ttarget\tone_pencil_status\tshifted_status\tshift_adds\tanchor_scans\tcandidate_prepared\tcontrol_prepared_derived\tcandidate_visited\tcontrol_visited\n");let mut totals=[0usize;5];let mut rows=vec![];for(a,b)in first.lines().skip(1).zip(shifted.lines().skip(1)){let x:Vec<_>=a.split('\t').collect();let y:Vec<_>=b.split('\t').collect();assert_eq!(&x[..3],&y[..3]);assert_eq!(&x[18..22],&y[18..22]);let n=|j:usize|y[j].parse::<usize>().unwrap();let old=n(20)*(1<<n(0));totals[0]+=1;totals[1]+=usize::from(x[3]=="verified");totals[2]+=usize::from(y[3]=="verified");totals[3]+=n(22);totals[4]+=n(14);summary+=&format!("{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\n",y[0],y[1],y[2],x[3],y[3],y[22],y[5],y[12],old,y[13],y[19]);rows.push((n(0),n(1),n(2),n(12),old));}print!("{summary}");fs::write(p.join("SUMMARY.tsv"),summary).unwrap();let total=format!("unique_inputs={}\none_pencil_verified={}\nshifted_verified={}\nshift_adds={}\nshifted_prepared_unused_tails={}\ncontrol_count_vectors_equal=true\n",totals[0],totals[1],totals[2],totals[3],totals[4]);print!("{total}");fs::write(p.join("TOTALS.txt"),total).unwrap();let maximum=rows.iter().map(|r|r.3.max(r.4)).max().unwrap()as f64;let mut svg=String::from("<svg xmlns='http://www.w3.org/2000/svg' width='1050' height='510'><rect width='1050' height='510' fill='white'/><g font-family='Arial' fill='#183846'><text x='35' y='35' font-size='22'>Joint collision/LP solve: principal outputs prepared</text><text x='35' y='62' font-size='14'>Six source-verified successes in each displayed arm. Counts are not elapsed time or speed ratios.</text>");for(i,r)in rows.iter().enumerate(){let ox=65.+i as f64*160.;for(j,(count,col))in[(r.3,"#287f82"),(r.4,"#bd733a")].iter().enumerate(){let x=ox+j as f64*44.;let ht=*count as f64/maximum*235.;svg+=&format!("<rect x='{x}' y='{:.2}' width='33' height='{ht:.2}' fill='{col}'/><text x='{x}' y='{:.2}' font-size='14'>{count}</text>",350.-ht,340.-ht);}svg+=&format!("<text x='{ox}' y='381' font-size='15'>g{} / t{}</text><text x='{ox}' y='406' font-size='13'>p{}</text>",r.0,r.2,r.1);}svg+="<rect x='35' y='430' width='17' height='17' fill='#287f82'/><text x='60' y='444' font-size='14'>Bounded-shift joint core (recorded)</text><rect x='530' y='430' width='17' height='17' fill='#bd733a'/><text x='555' y='444' font-size='14'>Compact (derived tuples × 2^g)</text><text x='35' y='472' font-size='13'>Unused final tails included; anchor membership differs. First one-pencil failures retained separately.</text><text x='35' y='496' font-size='13'>hec_anchor_collision_20261116 / frozen controls / exact deterministic counts, no uncertainty estimate.</text></g></svg>";fs::write(p.join("COUNTS.svg"),svg).unwrap();}
